// Bundles backend/core/*.js + gas/*.gs into one file to paste into Google Apps Script.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'backend')
const read = (dir, ext) => fs.readdirSync(path.join(root, dir)).filter((f) => f.endsWith(ext)).sort()
  .map((f) => `// ---- ${dir}/${f}\n` + fs.readFileSync(path.join(root, dir, f), 'utf8'))

const out = [
  '// GENERATED by `npm run backend:bundle`. Do not edit here; edit backend/core and backend/gas.',
  ...read('core', '.js'),
  ...read('gas', '.gs'),
].join('\n')

fs.mkdirSync(path.join(root, 'dist'), { recursive: true })
fs.writeFileSync(path.join(root, 'dist', 'Code.gs'), out)
fs.writeFileSync(path.join(root, 'dist', 'appsscript.json'), JSON.stringify({
  timeZone: 'Asia/Kolkata',
  exceptionLogging: 'STACKDRIVER',
  runtimeVersion: 'V8',
  webapp: { executeAs: 'USER_DEPLOYING', access: 'ANYONE_ANONYMOUS' },
  oauthScopes: [
    'https://www.googleapis.com/auth/spreadsheets',
    'https://www.googleapis.com/auth/drive',
    'https://www.googleapis.com/auth/script.send_mail',
    'https://www.googleapis.com/auth/script.external_request',
    'https://www.googleapis.com/auth/script.scriptapp',
    'https://www.googleapis.com/auth/userinfo.email',
  ],
}, null, 2))
console.log(`Wrote backend/dist/Code.gs (${(out.length / 1024).toFixed(0)} KB) and appsscript.json`)
